 "closing": {
  "lines": {
   "done": "Thank you for your time, [title] [last_name]. Goodbye.",
   "default": "Thank you for your time. Goodbye.",
   "transfer": "I am transferring you now. Thank you for your time, goodbye.",
   "callback": "Thank you, we will call back then. Goodbye.",
   "no_callback": "Thank you for your time. Goodbye.",
   "wrong_number": "I apologise for the inconvenience. Thank you, goodbye.",
   "deceased": "I am sorry for your loss. Thank you, goodbye.",
   "unclear": "Thank you for your time. Goodbye.",
   "declined_pre": "I understand. Thank you for your time, goodbye.",
   "declined": "I understand. Thank you for your time, goodbye.",
   "failed": "I am sorry, I could not verify your identity, so I cannot continue. Please use the Freya Bank mobile app or visit a branch. Thank you, goodbye.",
   "account_error": "I am sorry, I cannot access your account details right now because of a technical problem, so I cannot continue this call. Thank you for your time, goodbye.",
